local EVENTNAME = {
	GET_CLUB_POINT_RANKING = "/getClubPointRanking",
}

function ScoreRank:ctor(parents)
    self.parents = parents
    local csbPath = "hall/res/FriendScircle/ScoreRank/ScoreRankView.csb"
    ScoreRank.super.ctor(self, csbPath)

    self:enableMask(true)
    self:initEvent()
    --add by zzy
    self.AllHeHuoRenList = {}
	self.allPartnerList = {}
    self.curPage = 1
	self.page_num = 10
	self.tatolPage = 1
