    self:InitGame()
end
function ScoreRank:initEvent()
	
    ReqMgr:addHandle("ScoreRank", EVENTNAME)
    self.btn_r:onClick(handler(self, self.btn_r_page))
	self.btn_l:onClick(handler(self, self.btn_l_page))
end

function ScoreRank:onExit()
    ReqMgr:delHandle("ScoreRank", EVENTNAME)
end
