function ScoreRank:createTableView()
    self.userList = cc.TableView:create(cc.size(1188.00, 478))
    self.userList:setDirection(cc.SCROLLVIEW_DIRECTION_VERTICAL)
    self.userList:setVerticalFillOrder(cc.TABLEVIEW_FILL_TOPDOWN)
    self.userList:setAnchorPoint(cc.p(0, 0))
    self.userList:setPosition(cc.p(50.39, 94.55))
    self.userList:setDelegate()
   
    self.userList:addTo(self.root,99)
    self.userList:registerScriptHandler(handler(self, self.tableCellAtIndex), cc.TABLECELL_SIZE_AT_INDEX)
    self.userList:registerScriptHandler(handler(self, self.tableCellTouched), cc.TABLECELL_TOUCHED)
    self.userList:registerScriptHandler(self.cellSizeForTable, cc.TABLECELL_SIZE_FOR_INDEX)
    self.userList:registerScriptHandler(handler(self, self.numberOfCellsInTableView), cc.NUMBER_OF_CELLS_IN_TABLEVIEW)
    self.userList:reloadData()
end

--test
function ScoreRank:tableCellAtIndex(view, idx)
    local cell = view:dequeueCell()
    local item = nil
    if nil == cell then
        cell = cc.TableViewCell:new()
        local userBar = self:createUser(self.AllHeHuoRenList[idx+1], idx + 1)
        cell:addChild(userBar)
    else
        local node = cell:getChildByName("ly"):getChildByName("item")
        self:initCellInfo(node,self.AllHeHuoRenList[idx+1], idx + 1)
    end
    return cell
end

function ScoreRank:initCellInfo(item, data, index)
    local playerId = data.playerId or ""
    local pointCount = data.pointCount/100
    local nickName = data.nickName or ""
    local photo = data.photo
    local dayingjiaCount = data.dayingjiaCount
    pointCount = string.format("%.2f", pointCount)
    local head = item.head
    local width = head:getContentSize().width
    item.name:setString(nickName)
    item.id:setString(playerId)
    item.dyj:setString(dayingjiaCount)
    item.score:setString(pointCount)
    local scale = 70 /item.name:getContentSize().width
    if scale > 1 then
        scale = 1
    end
    item.name:setScale(scale)
    if self.curPage ~= 1 then
        index = self.page_num * (self.curPage - 1) + index
    end
    if self.curPage == 1 and index <= 3 then
        item.rankImg:show()
        item.rank:hide()
        item.rankImg:loadTexture("hall/res/FriendScircle/ScoreRank/icon_"..index..".png")
    else
        item.rank:setString(index)
        item.rankImg:hide()
        item.rank:show()
    end
    require("hall.GameCommon"):getUserHead(photo, "", "", head, width , false, "", true)
end

