function ScoreRank:numberOfCellsInTableView()
    if not (self and self.AllHeHuoRenList) then return end
    return #self.AllHeHuoRenList or 0
end


function ScoreRank:InitGame(page, playerId)
	page = page or 1
    local data = {groupId = self.parents.family_id, playerId = USER_INFO.uid, pageSize = self.page_num, currentPage = page}
    if tonumber(playerId) then
        data["playerId"] = tonumber(playerId)
    end
    dump(data)
    ReqMgr:request(EVENTNAME.GET_CLUB_POINT_RANKING, data, handler(self , self.FlushPartnerInfo), {page = page})
end

function ScoreRank:FlushPartnerInfo(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end
    dump(data,"FlushPartnerInfo_data")
    self.AllHeHuoRenList = {}
    self.AllHeHuoRenList = data.list
	self.allPartnerList = data

    self.tatolPage = math.ceil(data.listCount / self.page_num)
	if self.tatolPage == 0 then
        self.tatolPage = 1
    end
	self.curPage = param.page
    self.txt_page:setString(self.curPage.."/"..self.tatolPage)
    self:FlushPartnerList_new(data)
    
end

function ScoreRank:FlushPartnerList_new(data)
    if not data.list then return end
    self.userList:reloadData()
end

function ScoreRank:onClickBtnReturn(...)
    self:removeSelf()
end

function ScoreRank:btn_r_page()
	local page = self.curPage + 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

function ScoreRank:btn_l_page()
	local page = self.curPage - 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

return ScoreRank